      }
      const success = taskColors.every(color => usedColors.has(color));
      showResult(success);
    }
    function rgbToHex(r, g, b) {
      const c2h = c => { const h = c.toString(16); return h.length === 1 ? '0'+h : h; };
      return '#' + c2h(r) + c2h(g) + c2h(b);
    }
    function showResult(success) {
      resultElement.textContent = success ? 'Success!' : '';
    }
    function autoDrawAndSubmit() {
      // Draw the three required colors as pixels
      const colors = ['#4b0082', '#808000', '#ffff00'];
      colors.forEach((color, i) => {
        ctx.fillStyle = color;
        ctx.fillRect(i * 10, 0, 10, 10);
      });
      submitTask();
    }
    function init() {
      taskColors = generateRandomColors(3);
      displayTaskColors();
      createColorPalette();
      autoDrawAndSubmit();
    }
    canvas.addEventListener('mousedown', startDrawing);
    canvas.addEventListener('mousemove', draw);
    canvas.addEventListener('mouseup', stopDrawing);
    canvas.addEventListener('mouseout', stopDrawing);
    canvas.addEventListener('touchstart', startDrawing);
    canvas.addEventListener('touchmove', draw);
    canvas.addEventListener('touchend', stopDrawing);
    let isDrawing = false, lastX = 0, lastY = 0;
    function startDrawing(e) {
      isDrawing = true;
      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width, scaleY = canvas.height / rect.height;
      lastX = ((e.clientX || e.touches[0].clientX) - rect.left) * scaleX;
      lastY = ((e.clientY || e.touches[0].clientY) - rect.top) * scaleY;
    }
    function draw(e) {
      if (!isDrawing) return;
      e.preventDefault();
      const rect = canvas.getBoundingClientRect();
      const scaleX = canvas.width / rect.width, scaleY = canvas.height / rect.height;
      const currentX = ((e.clientX || e.touches[0].clientX) - rect.left) * scaleX;
      const currentY = ((e.clientY || e.touches[0].clientY) - rect.top) * scaleY;
      ctx.beginPath(); ctx.moveTo(lastX, lastY); ctx.lineTo(currentX, currentY); ctx.stroke();
      [lastX, lastY] = [currentX, currentY];
    }
    function stopDrawing() { isDrawing = false; }
    init();
    clearButton.addEventListener('click', clearCanvas);
    submitButton.addEventListener('click', submitTask);
  </script>
